contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sentValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sentValue)); require(sentValue <= 1000000000000000000000000000000);
        require(address(this).balance >= sentValue);

        uint prePot = c.pot(); if (__ESBMC_reverted()) return;
        uint preBalance = address(c).balance;

        bool reverted;
        c.play{value: sentValue}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postPot = c.pot(); if (__ESBMC_reverted()) return;
        uint postBalance = address(c).balance;

        assert(
            (reverted && postPot == prePot && postBalance == preBalance) ||
            (!reverted && (
                (postPot == 0 && postBalance == preBalance) ||
                (postPot == prePot + sentValue && postBalance == preBalance + sentValue)
            ))
        );
    }

    receive() external payable {}
}

