pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sentValue) internal {
        sentValue = bound(sentValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sentValue);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        uint preBalance = address(c).balance;
        bool reverted;
        try c.play{value: sentValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 postPot;
        try c.pot() returns (uint256 __r) { postPot = __r; } catch { return; }
        uint postBalance = address(c).balance;
        assertTrue((reverted && postPot == prePot && postBalance == preBalance) ||
            (!reverted && (
                (postPot == 0 && postBalance == preBalance) ||
                (postPot == prePot + sentValue && postBalance == preBalance + sentValue)
            )));
    }

    function testFuzz_run(uint256 sentValue) public {
        _run(sentValue);
    }

    receive() external payable {}
}
